package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art._
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Upstream_Acquisition_Qualification_Api {
  def id: Art.BridgeId
  def acquisition_sample_Id : Art.PortId
  def qualified_acquisition_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_acquisition: EIT_Image_Availability_Coordinator.Qualified_Acquisition.Type = $

  def put_qualified_acquisition(value : EIT_Image_Availability_Coordinator.Qualified_Acquisition.Type) : Unit = {
    Contract(
      Modifies(qualified_acquisition),
      Ensures(
        qualified_acquisition == value
      )
    )
    Spec {
      qualified_acquisition = value
    }

    Art.putValue(qualified_acquisition_Id, EIT_Image_Availability_Coordinator.Qualified_Acquisition_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Upstream_Acquisition_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val acquisition_sample_Id : Art.PortId,
  val qualified_acquisition_Id : Art.PortId) extends Upstream_Acquisition_Qualification_Api

@datatype class Upstream_Acquisition_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val acquisition_sample_Id : Art.PortId,
  val qualified_acquisition_Id : Art.PortId) extends Upstream_Acquisition_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var acquisition_sample: EIT_Image_Availability_Coordinator.Acquisition_Sample = $

  def get_acquisition_sample() : Option[EIT_Image_Availability_Coordinator.Acquisition_Sample] = {
    Contract(
      Ensures(
        Res == Some(acquisition_sample)
      )
    )
    val value : Option[EIT_Image_Availability_Coordinator.Acquisition_Sample] = Art.getValue(acquisition_sample_Id) match {
      case Some(EIT_Image_Availability_Coordinator.Acquisition_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port acquisition_sample.  Expecting 'EIT_Image_Availability_Coordinator.Acquisition_Sample_Payload' but received ${v}")
        None[EIT_Image_Availability_Coordinator.Acquisition_Sample]()
      case _ => None[EIT_Image_Availability_Coordinator.Acquisition_Sample]()
    }
    return value
  }
}
